// RagsServer is the server API for Rags service.
// All implementations must embed UnimplementedRagsServer
// for forward compatibility.
//
// Provides RAG and web crawler endpoints.
// Most of the RAG related endpoints largely mirror <a href="https://github.com/ondewo/ragflow">RAGFlow's</a> HTTP API endpoints. For more information on RAGFlow refer to the <a href="https://ragflow.io/docs/dev/">official documentation</a>
type RagsServer interface {
	// Create a new dataset (knowledge base).<br>
	RagCreateDataset(context.Context, *RagCreateDatasetRequest) (*RagDataset, error)
	// Update an existing dataset's configuration.<br>
	RagUpdateDataset(context.Context, *RagUpdateDatasetRequest) (*RagDataset, error)
	// Delete one or more datasets (batch operation).<br>
	// If ids is null or empty, deletes all user's datasets.<br>
	// Deletes all associated documents, files, and chunks.
	RagDeleteDatasets(context.Context, *RagDeleteRequest) (*RagPartialSuccess, error)
	// List datasets with pagination and filtering.<br>
	// Returns datasets from all tenants the user has access to.
	RagListDatasets(context.Context, *RagListDatasetsRequest) (*RagDatasetList, error)
	// Uploads a document to a dataset and starts parsing it.<br>
	// If the <code>run</code> field of the returned document is not <code>RAG_DOCUMENT_STATUS_RUNNING</code> this indicates a failure to start parsing the document.
	RagUploadDocument(grpc.ClientStreamingServer[RagUploadDocumentRequest, RagDocument]) error
	// Update document metadata and configuration.<br>
	// If the chunk method is changed, the document is automatically re-parsed.<br>
	// If the <code>run</code> field of the returned document is not <code>RAG_DOCUMENT_STATUS_RUNNING</code> this indicates a failure to start parsing the document.
	RagUpdateDocument(context.Context, *RagUpdateDocumentRequest) (*RagDocument, error)
	// Download the original document file.<br>
	// Returns binary file stream from storage.<br>
	// First chunk contains metadata, subsequent chunks only contain data.
	RagDownloadDocument(*RagDownloadDocumentRequest, grpc.ServerStreamingServer[RagFileChunk]) error
	// List documents in a dataset with pagination and filtering.<br>
	// Supports time range filtering and keyword search.
	RagListDocuments(context.Context, *RagListDocumentsRequest) (*RagDocumentList, error)
	// Delete one or more documents from a dataset (batch operation).<br>
	// If ids empty, deletes all documents. Removes chunks and storage files.
	RagDeleteDocuments(context.Context, *RagDeleteDocumentsRequest) (*RagPartialSuccess, error)
	// Retrieve chunks using vector similarity search.<br>
	// Supports reranking, metadata filtering, and knowledge graph retrieval.
	RagRetrieval(context.Context, *RagRetrievalRequest) (*RagRetrievalResponse, error)
	// Start parsing documents into chunks.<br>
	// Queues documents for background processing.
	RagParseDocuments(context.Context, *RagDocumentIdsRequest) (*RagPartialSuccess, error)
	// Stop parsing documents.
	RagStopParsing(context.Context, *RagDocumentIdsRequest) (*RagPartialSuccess, error)
	// Create a rag crawler for a dataset of an agent.
	RagCreateCrawler(context.Context, *RagCreateCrawlerRequest) (*RagCrawler, error)
	// Get a rag crawler by resource name.
	RagGetCrawler(context.Context, *RagGetCrawlerRequest) (*RagCrawler, error)
	// List rag crawlers of a dataset for the specified agent.
	RagListCrawlers(context.Context, *RagListCrawlersRequest) (*RagListCrawlersResponse, error)
	// Update a rag crawler (partial update of configuration fields).
	RagUpdateCrawler(context.Context, *RagUpdateCrawlerRequest) (*RagCrawler, error)
	// Delete a rag crawler of a dataset for the specified agent.
	RagDeleteCrawler(context.Context, *RagDeleteCrawlerRequest) (*RagDeleteCrawlerResponse, error)
	// Run a crawler.
	RagStartCrawler(context.Context, *RagStartCrawlerRequest) (*Operation, error)
	// Stop a pending or running crawler run.
	RagStopCrawler(context.Context, *RagStopCrawlerRequest) (*RagStopCrawlerResponse, error)
	// Get a crawler run by resource name.
	RagGetCrawlerRun(context.Context, *RagGetCrawlerRunRequest) (*Operation, error)
	// List crawler runs for a crawler.
	RagListCrawlerRuns(context.Context, *RagListCrawlerRunsRequest) (*RagListCrawlerRunsResponse, error)
	// Delete crawler runs by explicit run names and/or crawler names.
	RagDeleteCrawlerRuns(context.Context, *RagDeleteCrawlerRunsRequest) (*RagDeleteCrawlerRunsResponse, error)
	// Get a single crawler result by crawler run resource name and URL.
	RagGetCrawlerResult(context.Context, *RagGetCrawlerResultRequest) (*RagCrawlerResult, error)
	// Get crawler results by crawler run resource name.
	RagGetCrawlerResults(context.Context, *RagGetCrawlerResultsRequest) (*RagGetCrawlerResultsResponse, error)
	// Add rag crawler output to one or more datasets.
	RagAddCrawlerResultsToDatasets(context.Context, *RagAddCrawlerResultsToDatasetsRequest) (*Operation, error)
	// Remove previously imported crawler output from one or more datasets.
	RagRemoveCrawlerResultsFromDatasets(context.Context, *RagRemoveCrawlerResultsFromDatasetsRequest) (*Operation, error)
	// Get datasets currently attached to a crawler.
	RagGetCrawlerAttachedDatasets(context.Context, *RagGetCrawlerAttachedDatasetsRequest) (*RagGetCrawlerAttachedDatasetsResponse, error)
	// Delete multiple crawlers.
	RagDeleteCrawlers(context.Context, *RagDeleteCrawlersRequest) (*RagDeleteCrawlersResponse, error)
	// Get crawler run logs.
	RagGetCrawlerRunLogs(context.Context, *RagGetCrawlerRunLogsRequest) (*RagGetCrawlerRunLogsResponse, error)
	mustEmbedUnimplementedRagsServer()
}

